const menu = document.querySelector('.menu-button');
const nav = document.querySelector('#nav-links');
function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');nav.classList.remove('open');menu.innerHTML='Menu <span aria-hidden="true">☰</span>';}
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');nav.classList.toggle('open',open);menu.innerHTML=open?'Close <span aria-hidden="true">×</span>':'Menu <span aria-hidden="true">☰</span>';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus();}});
window.matchMedia('(min-width:761px)').addEventListener('change',e=>{if(e.matches)closeMenu();});
const art = (description,body,number,caption)=>`<svg viewBox="0 0 400 250" class="lab-art" role="img" aria-label="${description}">${body}<text x="25" y="26" font-family="monospace" font-size="8" fill="#737967">STUDY / 00${number}</text><text x="277" y="242" font-family="monospace" font-size="8" fill="#737967">${caption}</text></svg>`;
