const tabs=[...document.querySelectorAll('.lab-tab')];
if(tabs.length){tabData[0].art=document.querySelector('#lab-art').innerHTML;const selectTab=(i,focus=false)=>{tabs.forEach((tab,n)=>{tab.setAttribute('aria-selected',String(i===n));tab.tabIndex=i===n?0:-1;});const d=tabData[i];document.querySelector('#lab-panel').setAttribute('aria-labelledby',`lab-tab-${i}`);document.querySelector('#lab-caption').textContent=`Month 0${i+1} / ${d.title}`;document.querySelector('#lab-question').textContent=d.question;document.querySelector('#lab-description').textContent=d.description;document.querySelector('#lab-link').href=`/how-it-works/#month-0${i+1}`;document.querySelector('#lab-art').innerHTML=d.art;if(focus)tabs[i].focus();};tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectTab(i));tab.addEventListener('keydown',e=>{let n=i;if(e.key==='ArrowDown')n=(i+1)%tabs.length;else if(e.key==='ArrowUp')n=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();selectTab(n,true);});});}
